import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def find_message(payload, needle):
    return next(item for item in payload['items'] if needle in item['message'])

mut_borrow_await = verify('mut_borrow_await', '''
    fn touch(value: &'a mut i32) -> i32 {
        discard value
        return 0
    }
    async fn worker(v: &'a mut i32) -> i32 {
        await recv()
        return touch(v)
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
mut_diag = find_message(mut_borrow_await, 'call edge `worker -> touch` can hold mutable borrows across await boundary')
assert 'move the `await` before borrowing' in (mut_diag.get('help') or ''), mut_diag

borrowed_return_await = verify('borrowed_return_await', '''
    fn borrow(v: &'a i32) -> &'a i32 {
        return v
    }
    async fn worker(v: &'a i32) -> i32 {
        await recv()
        let alias = borrow(v)
        discard alias
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
ret_diag = find_message(borrowed_return_await, 'call edge `worker -> borrow` can propagate borrowed references across async suspension boundary')
assert 'resolve borrowed data before the suspension point' in (ret_diag.get('help') or ''), ret_diag

heavy_generic_await = verify('heavy_generic_await', '''
    fn project<T: Show>(value: &'a T) -> &'a T {
        return value
    }
    async fn worker(v: &'a i32) -> i32 {
        await recv()
        discard project<i32>(v)
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
generic_diag = find_message(heavy_generic_await, 'call edge `worker -> project` is generic/trait-heavy with borrowed parameters across await; inter-procedural lifetime summary rejected')
assert 'hand off owned values instead' in (generic_diag.get('help') or ''), generic_diag

borrow_local_await = verify('borrow_local_await', '''
    fn borrow(v: &'a i32) -> &'a i32 {
        return v
    }
    async fn worker(v: &'a i32) -> i32 {
        let alias = borrow(v)
        await recv()
        discard alias
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
assert any('cannot use borrowed local reference `alias` across await suspension points' in message for message in messages(borrow_local_await)), borrow_local_await

print('compiler-memory-async-borrow-edges-ok')

